#include "../models/conservative_beam/ConservativeBeam.cpp"
#include <sofa/component/statecontainer/MechanicalObject.h>
#include <random>
#include <iostream>
#include <iomanip>
using namespace regrip_beam;
void require(bool b,const char*s){if(!b)throw std::runtime_error(s);}
double maximum=0,jerror=0,momentError=0,objectivityError=0;
void verify(Pose a,Pose b,Pose a0,Pose b0,const Properties&p){
 auto r=evaluate(a,b,a0,b0,p);double eps=1e-6;
 for(int j=0;j<12;++j){auto ap=a,am=a,bp=b,bm=b;if(j<6){ap=increment(a,j,eps);am=increment(a,j,-eps);}else{bp=increment(b,j-6,eps);bm=increment(b,j-6,-eps);}auto rp=evaluate(ap,bp,a0,b0,p),rm=evaluate(am,bm,a0,b0,p);double ef=std::abs((rp.energy-rm.energy)/(2*eps)+r.force[j]);maximum=std::max(maximum,ef);require(ef<2e-6*(1+std::abs(r.force[j])),"energy virtual work FD");
  for(int i=0;i<12;++i){double fd=(rp.force[i]-rm.force[i])/(2*eps),err=std::abs(fd-r.jacobian[12*i+j]);jerror=std::max(jerror,err);require(err<3e-6*(1+std::abs(fd)),"spatial force derivative FD");require(std::abs(r.chart_hessian[12*i+j]-r.chart_hessian[12*j+i])<1e-10,"symmetric chart Hessian");}}
 V fa{r.force[0],r.force[1],r.force[2]},fb{r.force[6],r.force[7],r.force[8]},ta{r.force[3],r.force[4],r.force[5]},tb{r.force[9],r.force[10],r.force[11]};auto net=add(add(ta,tb),cross(sub(b.p,a.p),fb));for(int i=0;i<3;++i){require(std::abs(fa[i]+fb[i])<1e-10,"action reaction");momentError=std::max(momentError,std::abs(net[i]));require(std::abs(net[i])<1e-9,"total internal moment");}
 Q q=exp(V{1.3,-.7,1.8});auto aa=a,bb=b;aa.p=add(rotate(q,a.p),V{3,-2,1});bb.p=add(rotate(q,b.p),V{3,-2,1});aa.q=multiply(q,a.q);bb.q=multiply(q,b.q);auto obj=evaluate(aa,bb,a0,b0,p);require(std::abs(obj.energy-r.energy)<1e-9,"objective energy");for(int i:{0,3,6,9}){auto v=rotate(q,V{r.force[i],r.force[i+1],r.force[i+2]});for(int j=0;j<3;++j){objectivityError=std::max(objectivityError,std::abs(v[j]-obj.force[i+j]));require(std::abs(v[j]-obj.force[i+j])<1e-8,"objective force torque");}}
}
template<class Parent>struct Acc:Parent{double a[12][12]{};void add(sofa::SignedIndex r,sofa::SignedIndex c,double v)override{a[r][c]+=v;}void add(sofa::SignedIndex r,sofa::SignedIndex c,float v)override{add(r,c,double(v));}};
int main(){try{
 Pose a0,b0;b0.p={10,0,0};Properties p{183,60,60,8,10.6666666666667,10.6666666666667};auto r=evaluate(a0,b0,a0,b0,p);require(r.energy==0,"rest");for(double f:r.force)require(f==0,"rest force");
 auto axial=b0;axial.p[0]+=.02;require(std::abs(evaluate(a0,axial,a0,b0,p).energy-.5*p.EA*.02*.02/10)<1e-13,"pure axial");auto shear=b0;shear.p[1]=.03;require(std::abs(evaluate(a0,shear,a0,b0,p).energy-.5*p.GAy*.03*.03/10)<1e-13,"pure shear");auto twist=b0;twist.q=exp(V{.3,0,0});require(std::abs(evaluate(a0,twist,a0,b0,p).energy-.5*p.GJ*.3*.3/10)<1e-12,"pure torsion log");
 auto bend=b0;bend.q=exp(V{0,.2,0});bend.p=rotate(exp(V{0,.1,0}),V{10,0,0});require(std::abs(evaluate(a0,bend,a0,b0,p).energy-.5*p.EIy*.2*.2/10)<1e-12,"pure midpoint bending");verify(a0,bend,a0,b0,p);
 std::mt19937 gen(2911);std::uniform_real_distribution<double>d(-.3,.3);for(int s=0;s<60;++s){Pose a=a0,b=b0;for(int j=0;j<3;++j){a.p[j]+=d(gen);b.p[j]+=d(gen);}a.q=exp(V{d(gen),d(gen),d(gen)});b.q=exp(V{d(gen),d(gen),d(gen)});verify(a,b,a0,b0,p);}
 auto work=[&](int pieces){double sum=0;double q[5][2]={{0,0},{.1,0},{.1,.02},{0,.02},{0,0}};for(int s=0;s<4;++s){double dz=(q[s+1][0]-q[s][0])/pieces,da=(q[s+1][1]-q[s][1])/pieces;for(int i=0;i<pieces;++i){auto a=a0,b=b0;a.q=exp(V{0,q[s][1]+(i+.5)*da,0});b.p[2]+=q[s][0]+(i+.5)*dz;auto v=evaluate(a,b,a0,b0,p);sum+=v.force[8]*dz+v.force[4]*da;}}return sum;};double wc=work(64),wf=work(256);require(std::abs(wf)<1e-8&&std::abs(wf)<std::abs(wc)*.1,"closed work midpoint convergence");
 auto state=sofa::core::objectmodel::New<sofa::component::statecontainer::MechanicalObject<Types>>();state->resize(2);Base::VecCoord x(2);for(int i=0;i<2;++i){auto pose=i?b0:a0;for(int j=0;j<3;++j)x[i].getCenter()[j]=pose.p[j];x[i].getOrientation()={0,0,0,1};}state->write(sofa::core::vec_id::write_access::restPosition)->setValue(x);state->write(sofa::core::vec_id::write_access::position)->setValue(x);auto field=sofa::core::objectmodel::New<ConservativeBeam>(state.get());field->edges.setValue({0,1});field->init();x[1].getCenter()[2]=.01;state->write(sofa::core::vec_id::write_access::position)->setValue(x);auto actual=field->values(x)[0];Base::DataVecDeriv dx,df;Base::VecDeriv v(2);for(auto&dv:v)for(int j=0;j<6;++j)dv[j]=.01*(j+1);dx.setValue(v);df.setValue(Base::VecDeriv(2));sofa::core::MechanicalParams mp;mp.setKFactor(2.5);field->addDForce(&mp,df,dx);for(int i=0;i<12;++i){double expected=0;for(int j=0;j<12;++j)expected+=2.5*actual.jacobian[12*i+j]*v[j/6][j%6];require(std::abs(expected-df.getValue()[i/6][i%6])<1e-12,"addDForce kFactor");}
 Acc<sofa::core::behavior::StiffnessMatrixAccumulator>acc;sofa::core::behavior::StiffnessMatrix matrix;matrix.setMatrixAccumulator(&acc,state.get());field->buildStiffnessMatrix(&matrix);for(int i=0;i<12;++i)for(int j=0;j<12;++j)require(std::abs(acc.a[i][j]-actual.jacobian[12*i+j])<1e-14,"actual stiffness API");
 bool invalid=false;try{auto bad=b0;bad.q=exp(V{0,3,0});evaluate(a0,bad,a0,b0,p);}catch(const std::domain_error&){invalid=true;}require(invalid,"rotation branch safe");
 std::cout<<std::setprecision(17)<<"PASS conservative beam 61states/energy/spatialJ/objectivity/moment/API; energyFD="<<maximum<<" spatialJ="<<jerror<<" moment="<<momentError<<" covariance="<<objectivityError<<" closed64="<<wc<<" closed256="<<wf<<'\n';
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
